        .confirm => []const u8,
        .confirmations => []const std.json.Value,
        .delete_route => ?std.json.Value,
        .delist_all => []const []const u8,
        .delist_route => KeptRoute,
        .deposit => []const u8,
        .domain_status => DomainStatus,
        .download_browser => Browsers,
        .earnings => Earnings,
